#!/bin/bash
# ติดตั้งเว็บรับสมัครงาน LinkPro บนเซิร์ฟเวอร์ที่มีอยู่แล้ว (ไม่กระทบเว็บอื่นในเครื่อง)
# วิธีใช้ (ในเซิร์ฟเวอร์ ด้วยสิทธิ์ root):
#   bash install-linkpro.sh            (ใช้ลิงก์ jobs.<IP>.sslip.io อัตโนมัติ)
#   bash install-linkpro.sh jobs.example.com you@email.com   (ถ้ามีโดเมนของตัวเอง)
set -euo pipefail
IP=$(curl -fsS http://169.254.169.254/metadata/v1/interfaces/public/0/ipv4/address 2>/dev/null || hostname -I | awk '{print $1}')
DOMAIN="${1:-jobs.${IP//./-}.sslip.io}"
EMAIL="${2:-}"
PORT=3100
[ "$(id -u)" = 0 ] || { echo "กรุณารันด้วย sudo / root"; exit 1; }

echo "== 1) ตรวจ Node.js =="
NEED_NODE=1
if command -v node >/dev/null; then
  V=$(node -p 'process.versions.node'); MAJ=${V%%.*}; MIN=$(echo $V | cut -d. -f2)
  if [ "$MAJ" -gt 22 ] || { [ "$MAJ" -eq 22 ] && [ "$MIN" -ge 13 ]; }; then NEED_NODE=0; fi
fi
if [ "$NEED_NODE" = 1 ]; then
  echo "ติดตั้ง Node 22 แยกไว้ที่ /opt/linkpro/node (ไม่แตะ Node เดิมของเครื่อง)"
  mkdir -p /opt/linkpro/node
  curl -fsSL https://nodejs.org/dist/latest-v22.x/SHASUMS256.txt | grep 'linux-x64.tar.xz' | awk '{print $2}' | head -1 > /tmp/nodefile
  curl -fsSL "https://nodejs.org/dist/latest-v22.x/$(cat /tmp/nodefile)" | tar -xJ -C /opt/linkpro/node --strip-components=1
  NODE=/opt/linkpro/node/bin/node; NPM="/opt/linkpro/node/bin/node /opt/linkpro/node/bin/npm"
else
  NODE=$(command -v node); NPM=npm
fi

echo "== 2) ติดตั้งแอป =="
id linkpro >/dev/null 2>&1 || useradd -r -m -d /opt/linkpro -s /usr/sbin/nologin linkpro
mkdir -p /opt/linkpro/app /var/lib/linkpro
echo '' | base64 -d | tar -xJ -C /opt/linkpro/app
cd /opt/linkpro/app && $NPM install --omit=dev --no-audit --no-fund
chown -R linkpro:linkpro /opt/linkpro /var/lib/linkpro; chmod 700 /var/lib/linkpro

if [ ! -f /etc/linkpro.env ]; then
  PW="LP$(tr -dc 'A-Z0-9' </dev/urandom | head -c 8)"
  cat > /etc/linkpro.env <<ENV
PORT=$PORT
DATA_DIR=/var/lib/linkpro
ADMIN_PASSWORD=$PW
SESSION_SECRET=$(openssl rand -hex 32)
NODE_NO_WARNINGS=1
ENV
  chmod 600 /etc/linkpro.env
  echo ">> รหัสผ่านหน้าหลังบ้าน: $PW  (เก็บไว้ หรือแก้ได้ที่ /etc/linkpro.env)"
fi

cat > /etc/systemd/system/linkpro.service <<UNIT
[Unit]
Description=LinkPro Recruit
After=network.target
[Service]
User=linkpro
EnvironmentFile=/etc/linkpro.env
WorkingDirectory=/opt/linkpro/app
ExecStart=$NODE server.js
Restart=always
RestartSec=3
[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload && systemctl enable --now linkpro && systemctl restart linkpro
sleep 2; curl -fsS "http://127.0.0.1:$PORT/api/public/jobs" >/dev/null && echo "แอปทำงานที่พอร์ต $PORT แล้ว"

echo "== 3) ตั้งค่าเว็บเซิร์ฟเวอร์สำหรับ $DOMAIN =="
if command -v nginx >/dev/null; then
  cat > /etc/nginx/sites-available/$DOMAIN <<NGX
server {
  listen 80;
  server_name $DOMAIN;
  client_max_body_size 80M;
  location / {
    proxy_pass http://127.0.0.1:$PORT;
    proxy_set_header Host \$host;
    proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto \$scheme;
    proxy_read_timeout 120s;
  }
}
NGX
  ln -sf /etc/nginx/sites-available/$DOMAIN /etc/nginx/sites-enabled/$DOMAIN
  nginx -t && systemctl reload nginx
  if command -v certbot >/dev/null; then
    certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos $( [ -n "$EMAIL" ] && echo "-m $EMAIL" || echo "--register-unsafely-without-email" ) --redirect || echo "!! ขอ HTTPS ไม่สำเร็จ ตรวจว่า DNS ของ $DOMAIN ชี้มาที่เครื่องนี้แล้ว จากนั้นรัน: certbot --nginx -d $DOMAIN"
  else
    echo "!! ไม่พบ certbot: apt install -y certbot python3-certbot-nginx แล้วรัน certbot --nginx -d $DOMAIN"
  fi
elif command -v caddy >/dev/null; then
  echo "พบ Caddy: เพิ่มบล็อกนี้ใน /etc/caddy/Caddyfile แล้ว systemctl reload caddy"
  echo "$DOMAIN {"; echo "  request_body { max_size 80MB }"; echo "  reverse_proxy 127.0.0.1:$PORT"; echo "}"
else
  echo "!! ไม่พบ nginx หรือ Caddy: ให้ตั้ง reverse proxy ของ $DOMAIN ไปที่ http://127.0.0.1:$PORT"
fi

echo "== 4) สำรองข้อมูลทุกคืน (เก็บ 14 วัน) =="
cat > /etc/cron.daily/linkpro-backup <<'BAK'
#!/bin/bash
mkdir -p /var/backups/linkpro
D=$(date +%F)
cp /var/lib/linkpro/recruit.db /var/backups/linkpro/recruit-$D.db 2>/dev/null || true
tar -czf /var/backups/linkpro/uploads-$D.tgz -C /var/lib/linkpro uploads 2>/dev/null || true
find /var/backups/linkpro -type f -mtime +14 -delete
BAK
chmod +x /etc/cron.daily/linkpro-backup

echo ""
echo "เสร็จแล้ว: https://$DOMAIN  (หลังบ้าน: https://$DOMAIN/admin)"
